using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.IO;
using System.IO.Compression;
using System.Text;
using System.Web.Script.Serialization;
using System.Windows.Forms;

namespace SnapNote {
  class Mark { public string kind {get;set;} public int x1 {get;set;} public int y1 {get;set;} public int x2 {get;set;} public int y2 {get;set;} public string text {get;set;} public string note {get;set;} public int color {get;set;} }
  class Document { public string format {get;set;} public string image {get;set;} public List<Mark> marks {get;set;} }
  class Canvas : Control {
    public Bitmap Shot; public List<Mark> Marks = new List<Mark>(); public Mark Current; public string Tool="pen"; public Color Ink=Color.Red;
    public Canvas(){ DoubleBuffered=true; BackColor=Color.FromArgb(40,40,40); Cursor=Cursors.Cross; }
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e); if(Shot==null)return; e.Graphics.SmoothingMode=SmoothingMode.AntiAlias; e.Graphics.DrawImageUnscaled(Shot,0,0); foreach(var m in Marks) Draw(e.Graphics,m); if(Current!=null)Draw(e.Graphics,Current);}
    public static void Draw(Graphics g,Mark m){using(var p=new Pen(Color.FromArgb(m.color),3)){p.StartCap=LineCap.Round;p.EndCap=LineCap.ArrowAnchor; if(m.kind=="rect")g.DrawRectangle(p,Math.Min(m.x1,m.x2),Math.Min(m.y1,m.y2),Math.Abs(m.x2-m.x1),Math.Abs(m.y2-m.y1)); else if(m.kind=="arrow")g.DrawLine(p,m.x1,m.y1,m.x2,m.y2); else if(m.kind=="pen"){p.EndCap=LineCap.Round;g.DrawLine(p,m.x1,m.y1,m.x2,m.y2);} else if(m.kind=="text")using(var b=new SolidBrush(Color.FromArgb(m.color)))using(var f=new Font("Microsoft YaHei UI",18,FontStyle.Bold))g.DrawString(m.text??"",f,b,m.x1,m.y1); else if(m.kind=="number"){using(var b=new SolidBrush(Color.FromArgb(m.color)))g.FillEllipse(b,m.x1-15,m.y1-15,30,30);using(var f=new Font("Arial",14,FontStyle.Bold))using(var b=new SolidBrush(Color.White)){var size=g.MeasureString(m.text??"",f);g.DrawString(m.text??"",f,b,m.x1-size.Width/2,m.y1-size.Height/2);}}}}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(Shot==null||e.Button!=MouseButtons.Left||e.X<0||e.Y<0||e.X>=Shot.Width||e.Y>=Shot.Height)return; if(e.Clicks>1)return; if(Tool=="number"){int n=0;foreach(var mark in Marks)if(mark.kind=="number")n++;Marks.Add(new Mark{kind="number",x1=e.X,y1=e.Y,text=(n+1).ToString(),color=Ink.ToArgb()});Invalidate();return;} if(Tool=="text"){string s=Microsoft.VisualBasic.Interaction.InputBox("输入批注文字","文字批注","");if(s.Length>0){Marks.Add(new Mark{kind="text",x1=e.X,y1=e.Y,text=s,color=Ink.ToArgb()});Invalidate();}return;} Current=new Mark{kind=Tool,x1=e.X,y1=e.Y,x2=e.X,y2=e.Y,color=Ink.ToArgb()};Capture=true;}
    protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(Current==null)return;if(Tool=="pen"){var next=new Mark{kind="pen",x1=Current.x2,y1=Current.y2,x2=e.X,y2=e.Y,color=Ink.ToArgb()};Marks.Add(next);Current.x2=e.X;Current.y2=e.Y;}else{Current.x2=e.X;Current.y2=e.Y;}Invalidate();}
    protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(Current==null)return;Current.x2=e.X;Current.y2=e.Y;if(Tool!="pen"||Current.x1!=Current.x2||Current.y1!=Current.y2)Marks.Add(Current);Current=null;Capture=false;Invalidate();}
    protected override void OnMouseDoubleClick(MouseEventArgs e){base.OnMouseDoubleClick(e);for(int i=Marks.Count-1;i>=0;i--){var m=Marks[i];if(m.kind=="number"&&Math.Abs(m.x1-e.X)<20&&Math.Abs(m.y1-e.Y)<20){m.note=Microsoft.VisualBasic.Interaction.InputBox("为编号 "+m.text+" 输入说明","编号批注",m.note??"");Invalidate();return;}}}
    public Bitmap Flatten(){if(Shot==null)throw new InvalidOperationException("请先截图");var b=new Bitmap(Shot.Width,Shot.Height);using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.DrawImageUnscaled(Shot,0,0);foreach(var m in Marks)Draw(g,m);}return b;}
  }
  class Capture : Form {
    Bitmap screen; Point start; Rectangle box; public Bitmap Result;
    public Capture(){var bounds=SystemInformation.VirtualScreen;screen=new Bitmap(bounds.Width,bounds.Height);using(var g=Graphics.FromImage(screen))g.CopyFromScreen(bounds.Location,Point.Empty,bounds.Size);Bounds=bounds;FormBorderStyle=FormBorderStyle.None;TopMost=true;DoubleBuffered=true;Cursor=Cursors.Cross;KeyPreview=true;KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Escape)Close();};MouseDown+=(s,e)=>{start=e.Location;box=Rectangle.Empty;};MouseMove+=(s,e)=>{if(e.Button==MouseButtons.Left){box=Rectangle.FromLTRB(Math.Min(start.X,e.X),Math.Min(start.Y,e.Y),Math.Max(start.X,e.X),Math.Max(start.Y,e.Y));Invalidate();}};MouseUp+=(s,e)=>{if(box.Width>2&&box.Height>2){Result=screen.Clone(box,PixelFormat.Format32bppArgb);DialogResult=DialogResult.OK;}Close();};}
    protected override void OnPaint(PaintEventArgs e){e.Graphics.DrawImageUnscaled(screen,0,0);using(var shade=new SolidBrush(Color.FromArgb(100,0,0,0)))e.Graphics.FillRectangle(shade,ClientRectangle);if(box.Width>0&&box.Height>0){e.Graphics.DrawImage(screen,box,box,GraphicsUnit.Pixel);using(var p=new Pen(Color.DeepSkyBlue,2))e.Graphics.DrawRectangle(p,box);}}
    protected override void Dispose(bool d){if(d)screen.Dispose();base.Dispose(d);}
  }
  class MainForm : Form {
    Canvas canvas=new Canvas(); FlowLayoutPanel bar=new FlowLayoutPanel(); JavaScriptSerializer json=new JavaScriptSerializer();
    public MainForm(){
      Text="SnapNote · 拖入图片批注";Width=1100;Height=760;KeyPreview=true;AllowDrop=true;
      bar.Dock=DockStyle.Top;bar.Height=46;bar.Padding=new Padding(5);Controls.Add(bar);
      var panel=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Color.FromArgb(45,45,45),AllowDrop=true};
      panel.Controls.Add(canvas);Controls.Add(panel);panel.BringToFront();bar.BringToFront();
      Button("导入图片",()=>OpenImage());Button("粘贴图片",()=>PasteImage());
      foreach(var tool in new[]{"number","text","pen","rect","arrow"}){string t=tool;Button(new Dictionary<string,string>{{"number","编号 1 2 3"},{"text","文字"},{"pen","画笔"},{"rect","矩形"},{"arrow","箭头"}}[t],()=>canvas.Tool=t);}
      canvas.Tool="number";
      Button("颜色",()=>{using(var d=new ColorDialog{Color=canvas.Ink})if(d.ShowDialog()==DialogResult.OK)canvas.Ink=d.Color;});
      Button("撤销",()=>Undo());Button("保存 PNG",()=>SavePng());Button("保存文本",()=>SaveText());Button("保存 JSON",()=>SaveJson());Button("打开 JSON",()=>OpenJson());Button("导出 PPTX",()=>SavePptx());
      DragEnter+=OnDragEnter;DragDrop+=OnDragDrop;panel.DragEnter+=OnDragEnter;panel.DragDrop+=OnDragDrop;canvas.AllowDrop=true;canvas.DragEnter+=OnDragEnter;canvas.DragDrop+=OnDragDrop;
      KeyDown+=(s,e)=>{if(e.Control&&e.KeyCode==Keys.Z){Undo();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.V){PasteImage();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.O){OpenImage();e.SuppressKeyPress=true;}};
    }
    void Undo(){if(canvas.Marks.Count>0){canvas.Marks.RemoveAt(canvas.Marks.Count-1);canvas.Invalidate();}}
    void OnDragEnter(object sender,DragEventArgs e){if(e.Data.GetDataPresent(DataFormats.FileDrop))e.Effect=DragDropEffects.Copy;}
    void OnDragDrop(object sender,DragEventArgs e){var files=e.Data.GetData(DataFormats.FileDrop) as string[];if(files!=null&&files.Length>0)try{LoadImage(files[0]);}catch(Exception ex){MessageBox.Show(ex.Message,"导入失败");}}
    void LoadImage(string path){using(var source=Image.FromFile(path))SetShot(new Bitmap(source));}
    void OpenImage(){var path=Choose(false,"png","图片|*.png;*.jpg;*.jpeg;*.bmp;*.gif");if(path!=null)LoadImage(path);}
    void PasteImage(){if(!Clipboard.ContainsImage())return;using(var image=Clipboard.GetImage())SetShot(new Bitmap(image));}
    void SaveText(){if(canvas.Shot==null)return;var path=Choose(true,"txt","文本批注|*.txt");if(path==null)return;var lines=new List<string>();foreach(var m in canvas.Marks)if(m.kind=="number")lines.Add(m.text+". "+(m.note??"")+" ("+m.x1+", "+m.y1+")");else if(m.kind=="text")lines.Add("文字 ("+m.x1+", "+m.y1+"): "+m.text);File.WriteAllLines(path,lines.ToArray(),Encoding.UTF8);}
    void Button(string label,Action action){var b=new Button{Text=label,AutoSize=true,Height=32,Margin=new Padding(3)};b.Click+=(s,e)=>{try{action();}catch(Exception ex){MessageBox.Show(ex.Message,"SnapNote",MessageBoxButtons.OK,MessageBoxIcon.Error);}};bar.Controls.Add(b);}
    void SetShot(Bitmap b){if(canvas.Shot!=null)canvas.Shot.Dispose();canvas.Shot=b;canvas.Marks.Clear();canvas.Size=b.Size;canvas.Invalidate();}
    void Take(){Hide();Application.DoEvents();try{using(var c=new Capture())if(c.ShowDialog()==DialogResult.OK)SetShot(c.Result);}finally{Show();Activate();}}
    void Full(){Hide();Application.DoEvents();try{var r=SystemInformation.VirtualScreen;var b=new Bitmap(r.Width,r.Height);using(var g=Graphics.FromImage(b))g.CopyFromScreen(r.Location,Point.Empty,r.Size);SetShot(b);}finally{Show();Activate();}}
    string Choose(bool save,string ext,string filter){using(var d=save?(FileDialog)new SaveFileDialog():new OpenFileDialog()){d.Filter=filter;if(save)((SaveFileDialog)d).DefaultExt=ext;return d.ShowDialog()==DialogResult.OK?d.FileName:null;}}
    void SavePng(){if(canvas.Shot==null)return;var path=Choose(true,"png","PNG 图片|*.png");if(path==null)return;using(var b=canvas.Flatten())b.Save(path,ImageFormat.Png);}
    void SaveJson(){if(canvas.Shot==null)return;var path=Choose(true,"json","SnapNote 项目|*.json");if(path==null)return;using(var ms=new MemoryStream()){canvas.Shot.Save(ms,ImageFormat.Png);var doc=new Document{format="snapnote-1",image=Convert.ToBase64String(ms.ToArray()),marks=canvas.Marks};File.WriteAllText(path,json.Serialize(doc),Encoding.UTF8);}}
    void OpenJson(){var path=Choose(false,"json","SnapNote 项目|*.json");if(path==null)return;var doc=json.Deserialize<Document>(File.ReadAllText(path,Encoding.UTF8));if(doc==null||doc.format!="snapnote-1")throw new InvalidDataException("不支持的项目格式");using(var ms=new MemoryStream(Convert.FromBase64String(doc.image)))using(var temp=new Bitmap(ms))SetShot(new Bitmap(temp));canvas.Marks=doc.marks??new List<Mark>();canvas.Invalidate();}
    void SavePptx(){if(canvas.Shot==null)return;var path=Choose(true,"pptx","PowerPoint 演示文稿|*.pptx");if(path==null)return;using(var b=canvas.Flatten())Pptx.Write(path,b);}
  }
  static class Pptx {
    static void Add(ZipArchive z,string name,string content){var e=z.CreateEntry(name,CompressionLevel.Optimal);using(var w=new StreamWriter(e.Open(),new UTF8Encoding(false)))w.Write(content);}
